type SessionRoomCache={version:1;updatedAt:number;view?:any;secrets?:Record<string,{phase:string;round:number;actionVersion:number;secret:any}>;sharedCredentials?:any[]};
function readSessionRoom(code:string):SessionRoomCache|null{try{const raw=sessionStorage.getItem(`jinrou:session:${code}`);if(!raw)return null;const value=JSON.parse(raw) as SessionRoomCache;if(value.version!==1||Date.now()-value.updatedAt>24*60*60*1000)return null;return value}catch{return null}}
function readResumeOffer(){try{const code=sessionStorage.getItem('currentRoom')||'',dismissed=sessionStorage.getItem('jinrou:resume-dismissed');if(!/^\d{5}$/.test(code)||dismissed===code)return null;const cache=readSessionRoom(code),identity=JSON.parse(sessionStorage.getItem('jinrou:resume-identity')||'null'),seatUid=sessionStorage.getItem(`jinrou:last-seat:${code}`)||'';return {code,kind:identity?.code===code?identity.kind:cache?.view?.viewerKind==='spectator'?'spectator':'player',name:identity?.code===code?identity.name:'',seatUid}}catch{return null}}
function updateSessionRoom(code:string,patch:Partial<SessionRoomCache>,clearSecrets=false){try{const previous=readSessionRoom(code)||{version:1 as const,updatedAt:Date.now()};sessionStorage.setItem(`jinrou:session:${code}`,JSON.stringify({...previous,...patch,secrets:clearSecrets?(patch.secrets||{}):{...previous.secrets,...patch.secrets},updatedAt:Date.now()}))}catch{/* Storage quota/private mode should not stop the game. */}}
